Here is the revised function that avoids integer string length limits:

```python
from itertools import zip_longest

def compare_versions(a: str, b: str) -> int:
    def parse(s: str) -> list[tuple[int, str]]:
        parts = s.split('.')
        res = []
        for part in parts:
            if not (part.isascii() and part.isdigit()):
                raise ValueError("version parts must be non-empty decimal digit strings")
            stripped = part.lstrip('0')
            res.append((len(stripped), stripped))
        return res

    for x, y in zip_longest(parse(a), parse(b), fillvalue=(0, '')):
        if x < y:
            return -1
        if x > y:
            return 1
    return 0
```

